sum-of-root-to-leaf-binary-numbers:
# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def sumRootToLeaf(self, root) -> int:
        def dfs(node, val):
            if not node: return 0
            val = val*2 + node.val
            if not node.left and not node.right: return val
            return dfs(node.left, val) + dfs(node.right, val)
        return dfs(root, 0)

remove-outermost-parentheses:
class Solution:
    def removeOuterParentheses(self, s: str) -> str:
        res = []
        depth = 0
        for c in s:
            if c == '(':
                if depth > 0: res.append(c)
                depth += 1
            else:
                depth -= 1
                if depth > 0: res.append(c)
        return ''.join(res)

binary-prefix-divisible-by-5:
class Solution:
    def prefixesDivBy5(self, nums: List[int]) -> List[bool]:
        res = []
        cur = 0
        for x in nums:
            cur = (cur*2 + x) % 5
            res.append(cur == 0)
        return res

complement-of-base-10-integer:
class Solution:
    def bitwiseComplement(self, n: int) -> int:
        if n == 0: return 1
        mask = 1
        while mask < n: mask = (mask << 1) | 1
        return n ^ mask

maximize-sum-of-array-after-k-negations:
class Solution:
    def largestSumAfterKNegations(self, nums: List[int], k: int) -> int:
        nums.sort()
        for i in range(len(nums)):
            if k and nums[i] < 0:
                nums[i] = -nums[i]; k -= 1
        if k % 2:
            nums.sort()
            nums[0] = -nums[0]
        return sum(nums)

check-if-string-is-a-prefix-of-array:
class Solution:
    def isPrefixString(self, s: str, words: List[str]) -> bool:
        cur = ""
        for w in words:
            cur += w
            if cur == s: return True
            if len(cur) > len(s) or not s.startswith(cur): return False
        return False

minimum-absolute-difference:
class Solution:
    def minimumAbsDifference(self, arr: List[int]) -> List[List[int]]:
        arr.sort()
        mn = min(arr[i+1]-arr[i] for i in range(len(arr)-1))
        return [[arr[i], arr[i+1]] for i in range(len(arr)-1) if arr[i+1]-arr[i] == mn]

count-largest-group:
class Solution:
    def countLargestGroup(self, n: int) -> int:
        from collections import Counter
        c = Counter(sum(int(d) for d in str(i)) for i in range(1, n+1))
        mx = max(c.values())
        return sum(1 for v in c.values() if v == mx)

