sorting-the-sentence:
class Solution:
    def sortSentence(self, s: str) -> str:
        words = s.split()
        arr = ['']*len(words)
        for w in words:
            idx = int(w[-1])-1
            arr[idx] = w[:-1]
        return ' '.join(arr)

