maximum-enemy-forts-that-can-be-captured:
class Solution:
    def captureForts(self, forts: List[int]) -> int:
        ans = 0
        i = 0
        n = len(forts)
        while i < n:
            if forts[i] == 1 or forts[i] == -1:
                j = i+1
                while j < n and forts[j] == 0: j +=  1
                if j < n and forts[j] == -forts[i]:
                    ans = max(ans, j-i-1)
                i = j
            else:
                i +=  1
        return ans

shortest-distance-to-target-string-in-a-:
class Solution:
    def closetTarget(self, words: List[str], target: str, startIndex: int) -> int:
        n = len(words)
        best = float('inf')
        for i in range(n):
            if words[i] == target:
                d = abs(startIndex-i)
                d = min(d, n-d)
                best = min(best, d)
        return best if best != float('inf') else -1
